from collections import defaultdict
class Solution:
    def maxStarSum(self, vals: List[int], edges: List[List[int]], k: int) -> int:
        adj = defaultdict(list)
        for u, v in edges:
            adj[u].append(vals[v])
            adj[v].append(vals[u])
        ans = max(vals)
        for i in range(len(vals)):
            ns = sorted(adj[i], reverse=True)[:k]
            ans = max(ans, vals[i] + sum(x for x in ns if x > 0))
        return ans

