    int maxStarSum(vector<int>& vals, vector<vector<int>>& edges, int k) {
        int n = vals.size();
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(vals[e[1]]);
            adj[e[1]].push_back(vals[e[0]]);
        }
        int ans = *max_element(vals.begin(), vals.end());
        for (int i = 0; i < n; i++) {
            sort(adj[i].rbegin(), adj[i].rend());
            int s = vals[i];
            for (int j = 0; j < min(k, (int)adj[i].size()) && adj[i][j] > 0; j++)
                s += adj[i][j];
            ans = max(ans, s);
        }
        return ans;
    }
};

