import heapq
from collections import defaultdict
class Solution:
    def maxStarSum(self, vals: List[int], edges: List[List[int]], k: int) -> int:
        adj = defaultdict(list)
        for u, v in edges:
            adj[u].append(vals[v])
            adj[v].append(vals[u])
        ans = max(vals)
        for i in range(len(vals)):
            h = []
            for x in adj[i]:
                heapq.heappush(h, x)
                if len(h) > k:
                    heapq.heappop(h)
            ans = max(ans, vals[i] + sum(x for x in h if x > 0))
        return ans

